module div_16bit (
    input wire [15:0] A,
    input wire [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;
reg [15:0] quotient;
reg [15:0] remainder;

always @(*) begin
    a_reg = A;
    b_reg = B;
    quotient = 0;
    remainder = 0;

    if (B == 0) begin
        result = 16'hFFFF;
        odd = A;
    end else begin
        for (int i = 15; i >= 0; i--) begin
            remainder = {remainder[7:0], a_reg[15]};
            a_reg = a_reg << 1;
            if (remainder >= b_reg) begin
                remainder = remainder - b_reg;
                quotient[i] = 1;
            end
        end
        result = quotient;
        odd = remainder;
    end
end

endmodule
